/* ItamarOS Game FX: original SVG decorations and Kenney CC0 sound effects.
   Wave sounds embedded for offline play; original files from
   https://github.com/Calinou/kenney-interface-sounds (Creative Commons CC0).
   Avoid audio auto-play: sounds only start after explicit user interaction. */
(()=>{
'use strict';
const sounds={"tap":"","move":"","collect":"","error":"","win":""};
const palette={"2048":["#ff7d47","#ffe575"],"snake":["#0f805e","#7ad86e"],"memory":["#6758ee","#f3a0ef"],"tictactoe":["#1e96e8","#61dbff"],"guess":["#7b58e5","#e8a2f7"],"reaction":["#ef9040","#ffec77"],"rps":["#ad58e5","#ff9cc7"],"math":["#327fea","#9fdbff"],"word":["#dd70ac","#f5d785"],"pattern":["#4d64cc","#7ad9dc"],"words":["#a05de6","#f9b5cc"],"connect":["#1f6ce0","#8fd5ff"]};
const symbols={"2048":"🔢","snake":"🐍","memory":"🃏","tictactoe":"⭕","guess":"🎯","reaction":"⚡","rps":"✊","math":"🧮","word":"🔤","words":"🧩","pattern":"🌈","connect":"🔴"};
const state={muted:false,enabled:true};
try{state.muted=localStorage.getItem('itamaros-game-sound')==='off'}catch{}
function play(name='tap'){
 if(state.muted)return;
 const raw=sounds[name]||sounds.tap;
 try{const audio=new Audio('data:audio/wav;base64,'+raw);audio.volume=.26;const p=audio.play();if(p&&p.catch)p.catch(()=>{});}catch{}
}
function badge(name){
 const [a,b]=palette[name]||palette.guess;
 const icon=symbols[name]||'🎮';
 // Draw colorful vector framing plus a character glyph. No copyrighted characters.
 const svg='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 480 170" role="img">'
  +'<defs><linearGradient id="g" x2="1" y2="1"><stop stop-color="'+a+'"/><stop offset="1" stop-color="'+b+'"/></linearGradient></defs>'
  +'<rect width="480" height="170" rx="25" fill="url(#g)"/>'
  +'<circle cx="400" cy="35" r="75" fill="white" opacity=".18"/><circle cx="48" cy="150" r="100" fill="white" opacity=".12"/>'
  +'<path d="M20 112 Q180 38 340 115 T495 72" stroke="white" stroke-width="12" fill="none" opacity=".21"/>'
  +'<text x="232" y="114" font-size="87" text-anchor="middle">'+icon+'</text>'
  +'<circle cx="75" cy="48" r="13" fill="#fff" opacity=".75"/><circle cx="90" cy="61" r="5" fill="#fff" opacity=".65"/>'
  +'<circle cx="370" cy="134" r="12" fill="#fff" opacity=".65"/>'
  +'</svg>';
 return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg);
}
function decorate(area,name){
 if(!area)return;
 const picture=document.createElement('img');
 picture.className='ios-game-art';
 picture.src=badge(name);picture.alt=name+' colorful game illustration';
 picture.decoding='async';
 area.prepend(picture);
 area.classList.add('ios-game-polished');
}
function controls(container){
 if(!container||container.querySelector('[data-fx-sound]'))return;
 const b=document.createElement('button');
 b.type='button';b.dataset.fxSound='1';b.className='ios-game-sound-toggle';
 b.textContent=state.muted?'🔇 Sounds off':'🔊 Sounds on';
 b.setAttribute('aria-label','Toggle game sound effects');
 b.addEventListener('click',()=>{
   state.muted=!state.muted;
   try{localStorage.setItem('itamaros-game-sound',state.muted?'off':'on')}catch{}
   b.textContent=state.muted?'🔇 Sounds off':'🔊 Sounds on';
   if(!state.muted)play('collect');
 });
 container.append(b);
}
function swipe(element,fn,threshold=24){
 if(!element)return;
 let start=null;
 element.style.touchAction='none';
 element.addEventListener('pointerdown',e=>{
  if(e.isPrimary===false)return;
  start={x:e.clientX,y:e.clientY,id:e.pointerId};
  if(element.setPointerCapture)try{element.setPointerCapture(e.pointerId)}catch{}
 });
 element.addEventListener('pointerup',e=>{
  if(!start||e.pointerId!==start.id)return;
  const dx=e.clientX-start.x,dy=e.clientY-start.y;start=null;
  if(Math.max(Math.abs(dx),Math.abs(dy))<threshold)return;
  const dir=Math.abs(dx)>Math.abs(dy)?(dx>0?'right':'left'):(dy>0?'down':'up');
  fn(dir,e);
 });
 element.addEventListener('pointercancel',()=>{start=null});
}
window.ItamarGameFX={play,badge,decorate,controls,swipe};
})();